parameters.jsCode:
const d = $json;

const toNumber = (v) =>
  v !== null && v !== undefined && v !== "" &&
  Number.isFinite(Number(v)) ? Number(v) : null;

const sugar = toNumber(d.sugars_100g);
const salt = toNumber(d.salt_100g);
const fat = toNumber(d.fat_100g);

const grade = String(d.nutriscore_grade ?? "")
  .trim().toLowerCase();

const enoughData =
  sugar !== null && salt !== null && fat !== null;

if (!enoughData) {
  return {
    json: {
      ...d,
      enough_data: false,
      message: "This product doesn't have enough nutrition data to classify."
    }
  };
}

const sugarLight =
  sugar < 5 ? "low" :
  sugar <= 22.5 ? "medium" : "high";

const saltLight = salt > 1.5 ? "high" : "not_high";
const fatLight = fat > 17.5 ? "high" : "not_high";

const concernScore = [
  sugarLight === "high",
  saltLight === "high",
  fatLight === "high"
].filter(Boolean).length;

const levels = ["healthy", "moderate", "unhealthy"];

const trafficLevel =
  concernScore === 0 ? "healthy" :
  concernScore === 1 ? "moderate" : "unhealthy";

const gradeLevel = {
  a: "healthy",
  b: "healthy",
  c: "moderate",
  d: "unhealthy",
  e: "unhealthy"
}[grade] ?? null;

const verdict = gradeLevel
  ? levels[Math.max(
      levels.indexOf(trafficLevel),
      levels.indexOf(gradeLevel)
    )]
  : trafficLevel;

return {
  json: {
    ...d,
    enough_data: true,
    traffic_lights: {
      sugar: sugarLight,
      salt: saltLight,
      fat: fatLight
    },
    concern_score: concernScore,
    traffic_level: trafficLevel,
    nutriscore_level: gradeLevel ?? "unknown",
    verdict
  }
};

